-- The transactional outbox and its deliveries (T336; constitution XVIII, contracts/events.md),
-- generated by Prisma from schema.prisma, plus the rules Prisma cannot express, hand-written at the
-- end: an event is history except for being marked relayed once, the relay finds unrelayed events
-- and unqueued deliveries by partial index, and a sent delivery records when it was sent.
-- CreateEnum
CREATE TYPE "DeliveryTarget" AS ENUM ('CRM', 'EMAIL', 'SMS');

-- CreateEnum
CREATE TYPE "DeliveryStatus" AS ENUM ('PENDING', 'SENDING', 'SENT', 'RETRYING', 'NEEDS_ATTENTION');

-- AlterTable
ALTER TABLE "Match" ADD COLUMN     "digestedAt" TIMESTAMP(3);

-- CreateTable
CREATE TABLE "OutboxEvent" (
    "id" TEXT NOT NULL,
    "type" TEXT NOT NULL,
    "aggregateType" TEXT NOT NULL,
    "aggregateId" TEXT NOT NULL,
    "payload" JSONB NOT NULL,
    "occurredAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "relayedAt" TIMESTAMP(3),
    "correlationId" TEXT,

    CONSTRAINT "OutboxEvent_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "Delivery" (
    "id" TEXT NOT NULL,
    "outboxEventId" TEXT NOT NULL,
    "target" "DeliveryTarget" NOT NULL,
    "recipientRef" TEXT NOT NULL,
    "status" "DeliveryStatus" NOT NULL DEFAULT 'PENDING',
    "attempts" INTEGER NOT NULL DEFAULT 0,
    "lastError" TEXT,
    "nextAttemptAt" TIMESTAMP(3),
    "queuedAt" TIMESTAMP(3),
    "sentAt" TIMESTAMP(3),
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "Delivery_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "OutboxEvent_aggregateType_aggregateId_occurredAt_idx" ON "OutboxEvent"("aggregateType", "aggregateId", "occurredAt");

-- CreateIndex
CREATE INDEX "Delivery_status_idx" ON "Delivery"("status");

-- CreateIndex
CREATE UNIQUE INDEX "Delivery_outboxEventId_target_recipientRef_key" ON "Delivery"("outboxEventId", "target", "recipientRef");

-- AddForeignKey
ALTER TABLE "Delivery" ADD CONSTRAINT "Delivery_outboxEventId_fkey" FOREIGN KEY ("outboxEventId") REFERENCES "OutboxEvent"("id") ON DELETE RESTRICT ON UPDATE CASCADE;


-- CreateIndex (hand-written): the relay's two scans, kept small by only indexing the work left.
CREATE INDEX "OutboxEvent_unrelayed_idx" ON "OutboxEvent"("occurredAt") WHERE "relayedAt" IS NULL;
CREATE INDEX "Delivery_unqueued_idx" ON "Delivery"("createdAt")
    WHERE "status" = 'PENDING' AND "queuedAt" IS NULL;

-- CreateTrigger (hand-written): an event never changes or disappears; the relay may only set
-- relayedAt, once.
CREATE FUNCTION "refuse_outbox_event_change"() RETURNS trigger AS $$
BEGIN
    IF TG_OP = 'UPDATE'
        AND OLD."relayedAt" IS NULL AND NEW."relayedAt" IS NOT NULL
        AND (to_jsonb(NEW) - 'relayedAt') = (to_jsonb(OLD) - 'relayedAt') THEN
        RETURN NEW;
    END IF;
    RAISE EXCEPTION 'OutboxEvent is append-only (only relayedAt may be set, once)';
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER "OutboxEvent_append_only" BEFORE UPDATE OR DELETE ON "OutboxEvent"
    FOR EACH ROW EXECUTE FUNCTION "refuse_outbox_event_change"();

-- AddCheck (hand-written): attempts never go negative, and a sent delivery says when.
ALTER TABLE "Delivery" ADD CONSTRAINT "Delivery_attempts_check" CHECK ("attempts" >= 0);
ALTER TABLE "Delivery" ADD CONSTRAINT "Delivery_sent_check" CHECK (
    ("status" = 'SENT') = ("sentAt" IS NOT NULL)
);
